<script setup lang="ts">
import { computed,h,onMounted,ref } from 'vue'
import { NAlert,NButton,NDataTable,NIcon,NSelect,NTag,useMessage } from 'naive-ui'
import { Download,Filter,ArrowUpRight,ArrowDownRight,Receipt } from '@vicons/tabler'
import { api,bytes,stamp } from '../api'
import {calendarRange} from '../calendar'
const props=defineProps<{me:any;zone:string}>();const message=useMessage()
const rows=ref<any[]>([]),meta=ref<any>({}),busy=ref(false),error=ref(''),timezone=ref(props.zone),grain=ref('day')
const initialRange=calendarRange(props.zone,7);const from=ref(initialRange.from),to=ref(initialRange.to)
function query(){const q=new URLSearchParams({from:from.value,to:to.value,grain:grain.value});return q.toString()}
async function load(){busy.value=true;error.value='';try{meta.value=await api('/api/usage?'+query());rows.value=meta.value.rows}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function quick(days:number,offset=0){const range=calendarRange(timezone.value,days,offset);from.value=range.from;to.value=range.to;load()}
async function download(){try{const data=await api('/api/usage?'+query());const rows=data.rows;const escape=(value:unknown)=>'"'+String(value??'').replaceAll('"','""')+'"';const csv='\uFEFF'+[['日期','倍率','计费上传字节','计费下载字节','计费用量字节'],...rows.map((r:any)=>[r.bucket,r.rate,r.up_bytes,r.down_bytes,r.billed_bytes])].map(r=>r.map(escape).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='onenew-usage.csv';a.click();URL.revokeObjectURL(url)}catch(e){message.error((e as Error).message)}}
const total=computed(()=>rows.value.reduce((a,r)=>({up:a.up+Number(r.up_bytes),down:a.down+Number(r.down_bytes),billed:a.billed+Number(r.billed_bytes)}),{up:0,down:0,billed:0}))
const columns=computed(()=>[{title:'归档日期',key:'bucket',minWidth:180},{title:'统计范围',key:'node_name',minWidth:130},{title:'上传',key:'up_bytes',minWidth:110,render:(r:any)=>bytes(r.up_bytes)},{title:'下载',key:'down_bytes',minWidth:110,render:(r:any)=>bytes(r.down_bytes)},{title:'计费用量',key:'billed_bytes',minWidth:120,render:(r:any)=>bytes(r.billed_bytes)},{title:'数据质量',key:'legacy',minWidth:110,render:(r:any)=>h(NTag,{size:'small',bordered:false,type:r.legacy?'warning':'success'},()=>r.legacy?'含旧协议':'面板日汇总')}])
onMounted(load)
</script>
<template><div class="page-heading"><div><span class="eyebrow">TRAFFIC</span><h1>流量统计</h1><p>按面板归档日期查询计费用量。</p></div><n-button secondary @click="download"><template #icon><n-icon :component="Download"/></template>导出 CSV</n-button></div><article class="surface filters"><div class="quick-ranges"><button @click="quick(1)">今天</button><button @click="quick(1,1)">昨天</button><button @click="quick(7)">近 7 天</button><button @click="quick(30)">近 30 天</button><span class="muted small">最多查询 366 天</span></div><div class="filter-grid"><label>开始归档日期<input v-model="from" type="date"/></label><label>结束归档日期<input v-model="to" type="date"/></label><label>面板归档时区<input :value="timezone" readonly/></label><label>聚合粒度<n-select v-model:value="grain" :options="[{label:'按天',value:'day'},{label:'按月',value:'month'}]"/></label><n-button type="primary" :loading="busy" @click="load"><template #icon><n-icon :component="Filter"/></template>查询</n-button></div></article><n-alert v-if="error" type="error" class="space-bottom">{{error}}</n-alert><n-alert v-if="meta.truncated" type="warning" class="space-bottom">结果超过 2000 组，请缩小范围以查看或导出完整数据。</n-alert><section class="stat-grid three"><article class="stat-card"><span class="stat-label">本次查询 · 上传</span><n-icon class="stat-icon" :component="ArrowUpRight"/><strong>{{bytes(total.up)}}</strong><small>计费上传字节</small></article><article class="stat-card"><span class="stat-label">本次查询 · 下载</span><n-icon class="stat-icon" :component="ArrowDownRight"/><strong>{{bytes(total.down)}}</strong><small>计费下载字节</small></article><article class="stat-card"><span class="stat-label">本次查询 · 计费用量</span><n-icon class="stat-icon" :component="Receipt"/><strong>{{bytes(total.billed)}}</strong><small>已包含节点计费倍率</small></article></section><article class="surface"><div class="section-heading"><div><h2>用量明细</h2><p>{{rows.length}} 组记录 · {{timezone}}</p></div><span class="muted small">更新于 {{stamp(meta.updated_at)}}</span></div><n-data-table :columns="columns" :data="rows" :loading="busy" :bordered="false" :scroll-x="900" :pagination="{pageSize:15}"/><p class="table-note">{{meta.note||'面板保存按日归档的计费用量。'}} CSV 保留精确计费字节数。</p></article></template>
